        if ($options !== null) {
            // A null property is omitted, so the server applies its own default.
            if ($options->useLagna !== null) {
                $params["useLagna"] = $options->useLagna;
            }
            if ($options->useMoon !== null) {
                $params["useMoon"] = $options->useMoon;
            }
            if ($options->useSun !== null) {
                $params["useSun"] = $options->useSun;
            }
            if ($options->noCorrectionInMoolatrikona !== null) {
                $params["noCorrectionInMoolatrikona"] = $options->noCorrectionInMoolatrikona;
            }
        }
        return $this->vedAstro->call("MoolaDasa", $params);
    }

